import{t as c,a1 as o,Z as n,a9 as t,cl as i,a8 as r,a7 as d,bU as s,bs as h,be as f}from"./index-DErtGJ6x.js";const l="https://visualizer.matthiasheckel.com/assets/bild-und-rahmen-screenshot-B4slOg0C.png",g={class:"lesson-page"},m={class:"shell"},u={class:"document-image"},v=["href"],b=["src"],k={class:"pager","aria-label":"Tutorialnavigation"},p={__name:"BildUndRahmenTutorial",setup(B){return(w,e)=>{const a=h("RouterLink");return f(),o("main",g,[n("div",m,[t(a,{to:"/medientechnik/adobe-indesign/mini-tutorials",class:"back"},{default:i(()=>[...e[0]||(e[0]=[r("← Mini Tutorials",-1)])]),_:1}),e[2]||(e[2]=d('<header data-v-9682cf66><p class="eyebrow" data-v-9682cf66>ADOBE INDESIGN · MINI TUTORIAL</p><h1 data-v-9682cf66>Bilder skalieren und beschneiden</h1><p class="goal" data-v-9682cf66>Entdecke, was der schwarze und der weiße Pfeil mit Bild und Rahmen machen.</p></header><section aria-labelledby="terms-title" data-v-9682cf66><h2 id="terms-title" data-v-9682cf66>Einfach erklärt</h2><dl data-v-9682cf66><div data-v-9682cf66><dt data-v-9682cf66>Rahmen</dt><dd data-v-9682cf66>Wie ein Fenster: Er bestimmt, welcher Teil des Bildes sichtbar ist. Verkleinerst du nur den Rahmen, wird das Bild beschnitten, aber nicht gelöscht.</dd></div><div data-v-9682cf66><dt data-v-9682cf66>Schwarzer Pfeil (V) · Auswahlwerkzeug</dt><dd data-v-9682cf66>Damit wählst du den Rahmen aus. Du kannst ihn mit dem Bild verschieben, nur den Rahmen verkleinern oder mit einer Tastenkombination beides skalieren.</dd></div><div data-v-9682cf66><dt data-v-9682cf66>Weißer Pfeil (A) · Direktauswahlwerkzeug</dt><dd data-v-9682cf66>Klicke damit auf das Bild im Rahmen, um den Bildinhalt auszuwählen. Du kannst dann das Bild im festen Rahmen verschieben oder seine Größe ändern. An Rahmenkanten und Ankerpunkten bearbeitet der weiße Pfeil dagegen die Rahmenform.</dd></div></dl></section>',2)),n("figure",u,[n("a",{href:s(l),target:"_blank",rel:"noopener noreferrer","aria-label":"Screenshot zu Bild und Rahmen vergrößern (neuer Tab)"},[n("img",{src:s(l),alt:"Strawberry-Motiv auf einer A4-Seite in Adobe InDesign als Beispiel zum Skalieren und Beschneiden."},null,8,b)],8,v)]),e[3]||(e[3]=d('<section class="practice" aria-labelledby="practice-title" data-v-9682cf66><h2 id="practice-title" data-v-9682cf66>So gehst du vor</h2><ol data-v-9682cf66><li data-v-9682cf66>Lege über <strong data-v-9682cf66>Datei → Neu → Dokument</strong> eine einzelne Seite im Format <strong data-v-9682cf66>A4, Hochformat</strong> an. Deaktiviere „Doppelseite“. Speichere das Dokument als <strong data-v-9682cf66>„Bild_und_Rahmen.indd“</strong> in deinem Namensordner.</li><li data-v-9682cf66><a href="/medientechnik/indesign/Strawberry.jpg" download="Strawberry.jpg" data-v-9682cf66>Strawberry.jpg herunterladen</a>: Speichere das Bild ebenfalls in deinem Namensordner.</li><li data-v-9682cf66><strong data-v-9682cf66>Bild direkt platzieren:</strong> Öffne <strong data-v-9682cf66>Datei → Platzieren (⌘ + D)</strong>, wähle <strong data-v-9682cf66>Strawberry.jpg</strong> und bestätige mit „Öffnen“. Ziehe mit dem geladenen Mauszeiger auf der leeren Seite das Bild in einer passenden Größe auf. InDesign legt den Bildrahmen dabei automatisch an.</li><li data-v-9682cf66><strong data-v-9682cf66>Rahmen und Bild verschieben:</strong> Aktiviere den <strong data-v-9682cf66>schwarzen Pfeil (V)</strong>. Klicke auf den Rahmenrand und ziehe ihn an eine andere Stelle. Rahmen und Bild bewegen sich gemeinsam. Klicke für diese Übung nicht auf den kreisförmigen Inhaltsauswahlgriff in der Bildmitte: Er wählt den Bildinhalt aus.</li><li data-v-9682cf66><strong data-v-9682cf66>Beschneiden – nur den Rahmen kleiner ziehen:</strong> Bleibe beim schwarzen Pfeil. Ziehe einen seitlichen oder unteren Griff des ausgewählten Rahmens nach innen, <strong data-v-9682cf66>ohne Zusatztaste</strong>. Das Bild bleibt gleich groß, aber du siehst einen kleineren Ausschnitt. Ziehe den Griff wieder nach außen: Die verdeckten Bildteile erscheinen wieder. Mit <strong data-v-9682cf66>Umschalt + Ziehen an einem Eckgriff</strong> behält nur der Rahmen seine Proportionen.</li><li data-v-9682cf66><strong data-v-9682cf66>Den Bildausschnitt verschieben:</strong> Wähle den <strong data-v-9682cf66>weißen Pfeil (A)</strong> und klicke auf das Bild innerhalb des Rahmens. Ziehe das Bild so, dass einer der Vögel im Ausschnitt zu sehen ist. Der Rahmen bleibt an seiner Position. Mit gedrückter <strong data-v-9682cf66>Umschalttaste</strong> verschiebst du das Bild waagerecht oder senkrecht.</li><li data-v-9682cf66><strong data-v-9682cf66>Nur das Bild proportional skalieren:</strong> Wähle den Bildinhalt mit dem weißen Pfeil aus. Halte <strong data-v-9682cf66>Umschalt</strong> gedrückt und ziehe an einem <strong data-v-9682cf66>Eckgriff der Bildbegrenzung</strong>. Das Muster wird größer oder kleiner, der Rahmen bleibt gleich groß. Achte darauf, einen Griff des Bildes und keinen Rahmenpunkt zu ziehen. Verkleinere das Bild nicht so weit, dass leere Stellen im Rahmen entstehen.</li><li data-v-9682cf66><strong data-v-9682cf66>Rahmen und Bild gemeinsam proportional skalieren:</strong> Wähle mit dem <strong data-v-9682cf66>schwarzen Pfeil</strong> den Rahmen aus. Halte auf dem Mac <strong data-v-9682cf66>⌘ + Umschalt</strong> gedrückt und ziehe an einem <strong data-v-9682cf66>Eckgriff</strong>. Unter Windows verwendest du <strong data-v-9682cf66>Strg + Umschalt</strong>. Lasse zuerst die Maustaste und dann die Tasten los. Bild und Rahmen ändern gemeinsam ihre Größe, ohne verzerrt zu werden.</li><li data-v-9682cf66>Probiere nochmals den Unterschied: Beschneide den Rahmen, verschiebe darin das Bild und skaliere anschließend beides gemeinsam. Speichere <strong data-v-9682cf66>„Bild_und_Rahmen.indd“</strong>.</li></ol><p data-v-9682cf66><strong data-v-9682cf66>Tipp:</strong> Mit <strong data-v-9682cf66>⌘ + Z</strong> (Windows: Strg + Z) machst du einen Versuch rückgängig. Die Werkzeugkürzel V und A funktionieren, wenn du gerade keinen Text bearbeitest.</p></section><section class="check" aria-labelledby="check-title" data-v-9682cf66><h2 id="check-title" data-v-9682cf66>Prüfe dein Ergebnis</h2><p data-v-9682cf66>Kannst du den sichtbaren Ausschnitt verändern, ohne das Muster zu skalieren? Kannst du anschließend Bild und Rahmen gemeinsam verkleinern, ohne die Vögel zu verzerren?</p></section><p class="source" data-v-9682cf66>Bei Adobe nachlesen: <a href="https://www.adobe.com/learn/indesign/web/add-work-with-graphics" target="_blank" rel="noopener noreferrer" data-v-9682cf66>Bilder und Rahmen skalieren ↗</a> · <a href="https://helpx.adobe.com/gr_en/indesign/desktop/add-graphics-and-media/manage-frames-and-objects/crop-objects.html" target="_blank" rel="noopener noreferrer" data-v-9682cf66>Bilder beschneiden ↗</a></p>',3)),n("nav",k,[t(a,{to:"/medientechnik/adobe-indesign/mini-tutorials"},{default:i(()=>[...e[1]||(e[1]=[r("← Zur Übersicht",-1)])]),_:1})])])])}}},z=c(p,[["__scopeId","data-v-9682cf66"]]);export{z as default};
